<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import AdminFilters from '../components/AdminFilters.vue'
import AdminPagination from '../components/AdminPagination.vue'
import AdminState from '../components/AdminState.vue'
import AdminTable from '../components/AdminTable.vue'
import { adminApi } from '../api/adminApi'
import { adminUserSchema } from '../schemas/adminSchemas'
import type { AdminUserDetail } from '../types/admin'
import { useFeedback } from '@/ui/feedback'

const route = useRoute(); const router = useRouter(); const feedback = useFeedback()
const users = ref<AdminUserDetail[]>([]); const selected = ref<AdminUserDetail | null>(null); const loading = ref(false); const error = ref(''); const pagination = ref({ page: 1, limit: 20, total: 0, totalPages: 0 })
const search = ref(String(route.query.search ?? '')); const roleFilter = ref(String(route.query.rol ?? '')); const activeFilter = ref(String(route.query.activo ?? ''))
const form = reactive<Record<string, any>>({ apellidoNombre: '', dni: '', email: '', fechaNacimiento: '', telefono: '', cuil: '', contactoEmergencia: '', foto: '', password: '', passwordConfirm: '', domicilio: '', anioEgreso: '', institucionProcedencia: '', role: 'ALUMNO' }); const fieldErrors = ref<Record<string, string>>({}); const saving = ref(false); const newRole = ref('')
const mode = computed(() => String(route.name ?? 'admin-users'))
const isList = computed(() => mode.value === 'admin-users'); const isCreate = computed(() => mode.value === 'admin-user-create'); const isEdit = computed(() => mode.value === 'admin-user-edit'); const isDetail = computed(() => mode.value === 'admin-user-detail'); const userId = computed(() => Number(route.params.id))

function queryPage(page = 1) { return { search: search.value || undefined, rol: roleFilter.value || undefined, activo: activeFilter.value || undefined, page: page > 1 ? String(page) : undefined } }
async function loadList(): Promise<void> { loading.value = true; error.value = ''; try { const result = await adminApi.listUsers({ search: search.value || undefined, rol: roleFilter.value || undefined, activo: activeFilter.value === '' ? undefined : activeFilter.value === 'true', page: Number(route.query.page ?? 1) }); users.value = result.data; pagination.value = result.pagination } catch { error.value = 'No pudimos cargar los usuarios.' } finally { loading.value = false } }
async function loadDetail(): Promise<void> { loading.value = true; error.value = ''; try { selected.value = await adminApi.getUser(userId.value); Object.assign(form, selected.value, { dni: String(selected.value.dni), role: selected.value.rol, domicilio: selected.value.alumno?.domicilio ?? '', anioEgreso: selected.value.alumno?.anioEgreso ?? '', institucionProcedencia: selected.value.alumno?.institucionProcedencia ?? '' }) } catch { error.value = 'No pudimos cargar el usuario.' } finally { loading.value = false } }
function applyFilters(): void { void router.replace({ query: queryPage(1) }).then(loadList) }
function resetForm(): void { Object.assign(form, { apellidoNombre: '', dni: '', email: '', fechaNacimiento: '', telefono: '', cuil: '', contactoEmergencia: '', foto: '', password: '', passwordConfirm: '', domicilio: '', anioEgreso: '', institucionProcedencia: '', role: 'ALUMNO' }); fieldErrors.value = {} }
function validationPayload(): Record<string, unknown> | null { fieldErrors.value = {}; const result = adminUserSchema.safeParse(form); if (!result.success) { for (const issue of result.error.issues) fieldErrors.value[String(issue.path[0])] = issue.message; return null } return { apellidoNombre: form.apellidoNombre.trim(), dni: String(form.dni), email: form.email.trim(), fechaNacimiento: form.fechaNacimiento, telefono: String(form.telefono), cuil: form.cuil || null, contactoEmergencia: form.contactoEmergencia || null, foto: form.foto || null, ...(form.role === 'ALUMNO' ? { alumno: { domicilio: form.domicilio, anioEgreso: Number(form.anioEgreso), institucionProcedencia: form.institucionProcedencia || null } } : {}) } }
async function save(): Promise<void> { if (isCreate.value && !form.password) { fieldErrors.value = { password: 'La contraseña inicial es requerida.' }; return }; const payload = validationPayload(); if (!payload) return; saving.value = true; try { if (isCreate.value) { await adminApi.createUser(form.role, { ...payload, password: form.password }); feedback.success('Cuenta creada.'); await router.replace({ name: 'admin-users' }) } else { await adminApi.updateUser(userId.value, payload); feedback.success('Usuario actualizado.'); await router.replace({ name: 'admin-user-detail', params: { id: userId.value } }) } } catch { feedback.error('No se pudo guardar el usuario.') } finally { saving.value = false } }
async function toggleActive(): Promise<void> { if (!selected.value) return; try { await adminApi.setUserActive(selected.value.idUsuario, !selected.value.activo); feedback.success(selected.value.activo ? 'Usuario desactivado.' : 'Usuario activado.'); await loadDetail() } catch { feedback.error('No se pudo cambiar el estado.') } }
async function addRole(): Promise<void> { if (!selected.value || !newRole.value) return; try { await adminApi.setUserRole(selected.value.idUsuario, newRole.value as any, newRole.value === 'ALUMNO' ? { domicilio: '', anioEgreso: null, institucionProcedencia: null } : undefined); newRole.value = ''; feedback.success('Rol agregado.'); await loadDetail() } catch { feedback.error('No se pudo agregar el rol.') } }
async function removeRole(role: string): Promise<void> { if (!selected.value || !window.confirm(`¿Quitar el rol ${role}?`)) return; try { await adminApi.removeUserRole(selected.value.idUsuario, role); feedback.success('Rol quitado.'); await loadDetail() } catch { feedback.error('No se pudo quitar el rol.') } }
onMounted(() => { if (isList.value) void loadList(); else if (isDetail.value || isEdit.value) void loadDetail(); else resetForm() })
watch(() => route.fullPath, () => { if (isList.value) void loadList(); else if (isDetail.value || isEdit.value) void loadDetail(); else if (isCreate.value) resetForm() })
</script>

<template>
  <main aria-labelledby="admin-users-title" class="mx-auto max-w-6xl">
    <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-semibold uppercase tracking-[0.14em] text-[var(--color-brand)]">Administración</p><h1 id="admin-users-title" class="mt-2 text-3xl font-semibold">Usuarios y roles</h1></div><RouterLink v-if="isList" :to="{ name: 'admin-user-create' }" class="min-h-11 rounded-lg bg-[var(--color-brand)] px-4 py-2.5 font-semibold text-white">Nueva cuenta</RouterLink></div>
    <template v-if="isList"><AdminFilters v-model:search="search" placeholder="Nombre, DNI o email" @submit="applyFilters"><label class="text-sm font-semibold">Rol<select v-model="roleFilter" class="mt-1 min-h-11 w-full rounded-lg border border-[var(--color-border)] px-3 font-normal"><option value="">Todos</option><option>ALUMNO</option><option>PROFESOR</option><option>ADMINISTRATIVO</option></select></label><label class="text-sm font-semibold">Estado<select v-model="activeFilter" class="mt-1 min-h-11 w-full rounded-lg border border-[var(--color-border)] px-3 font-normal"><option value="">Todos</option><option value="true">Activos</option><option value="false">Inactivos</option></select></label></AdminFilters><div class="mt-5"><AdminState :loading="loading" :error="error" :empty="!loading && !error && users.length === 0" empty-text="No hay usuarios con esos filtros." @retry="loadList"><AdminTable :columns="[{ key: 'name', label: 'Persona' }, { key: 'role', label: 'Rol' }, { key: 'status', label: 'Estado' }]"><template #rows><tr v-for="user in users" :key="user.idUsuario" class="border-t border-[var(--color-border)]"><td class="px-4 py-3"><RouterLink class="font-semibold text-[var(--color-brand)] hover:underline" :to="{ name: 'admin-user-detail', params: { id: user.idUsuario } }">{{ user.apellidoNombre }}</RouterLink><span class="block text-xs text-[var(--color-graphite)]">{{ user.email }} · DNI {{ user.dni }}</span></td><td class="px-4 py-3">{{ user.roles?.join(', ') ?? user.rol }}</td><td class="px-4 py-3">{{ user.activo ? 'Activo' : 'Inactivo' }}</td><td class="px-4 py-3 text-right"><RouterLink :to="{ name: 'admin-user-edit', params: { id: user.idUsuario } }" class="font-semibold text-[var(--color-brand)]">Editar</RouterLink></td></tr></template><template #cards><article v-for="user in users" :key="user.idUsuario" class="rounded-lg border border-[var(--color-border)] p-4"><RouterLink class="font-semibold text-[var(--color-brand)]" :to="{ name: 'admin-user-detail', params: { id: user.idUsuario } }">{{ user.apellidoNombre }}</RouterLink><p class="text-sm text-[var(--color-graphite)]">{{ user.email }} · {{ user.roles?.join(', ') ?? user.rol }}</p><p class="mt-2 text-sm">{{ user.activo ? 'Activo' : 'Inactivo' }}</p></article></template></AdminTable><AdminPagination class="mt-2" :pagination="pagination" @change="(page) => router.replace({ query: queryPage(page) }).then(loadList)" /></AdminState></div></template>
    <template v-else-if="isDetail"><AdminState :loading="loading" :error="error" @retry="loadDetail"><section v-if="selected" class="mt-7 grid gap-5 lg:grid-cols-[1fr_20rem]"><div class="rounded-xl border border-[var(--color-border)] bg-white p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="text-2xl font-semibold">{{ selected.apellidoNombre }}</h2><p class="text-[var(--color-graphite)]">{{ selected.email }} · DNI {{ selected.dni }}</p></div><span class="rounded-full px-3 py-1 text-sm font-semibold" :class="selected.activo ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-700'">{{ selected.activo ? 'Activo' : 'Inactivo' }}</span></div><dl class="mt-6 grid gap-4 sm:grid-cols-2"><div><dt class="text-sm text-[var(--color-graphite)]">Teléfono</dt><dd>{{ selected.telefono }}</dd></div><div><dt class="text-sm text-[var(--color-graphite)]">Roles</dt><dd>{{ selected.roles.join(', ') }}</dd></div><div v-if="selected.alumno" class="sm:col-span-2"><dt class="text-sm text-[var(--color-graphite)]">Ficha de alumno</dt><dd>{{ selected.alumno.domicilio }} · egreso {{ selected.alumno.anioEgreso ?? '—' }}</dd></div></dl><div class="mt-7 flex flex-wrap gap-3"><RouterLink :to="{ name: 'admin-user-edit', params: { id: selected.idUsuario } }" class="min-h-11 rounded-lg bg-[var(--color-brand)] px-4 py-2.5 font-semibold text-white">Editar datos</RouterLink><button type="button" class="min-h-11 rounded-lg border border-[var(--color-border)] px-4 py-2.5" @click="toggleActive">{{ selected.activo ? 'Desactivar' : 'Activar' }}</button></div></div><aside class="rounded-xl border border-[var(--color-border)] bg-white p-6"><h3 class="font-semibold">Roles asignados</h3><ul class="mt-3 space-y-2"><li v-for="role in selected.roles" :key="role" class="flex items-center justify-between rounded-lg bg-[#f6f7f4] px-3 py-2 text-sm"><span>{{ role }}</span><button type="button" class="text-[var(--color-brand)]" @click="removeRole(role)">Quitar</button></li></ul><div class="mt-4 flex gap-2"><select v-model="newRole" aria-label="Nuevo rol" class="min-h-10 min-w-0 flex-1 rounded-lg border border-[var(--color-border)] px-2"><option value="">Agregar rol</option><option v-for="role in ['ALUMNO','PROFESOR','ADMINISTRATIVO'].filter((role) => !selected?.roles.includes(role as any))" :key="role" :value="role">{{ role }}</option></select><button type="button" class="min-h-10 rounded-lg bg-[var(--color-brand)] px-3 text-sm font-semibold text-white" :disabled="!newRole" @click="addRole">Agregar</button></div><p class="mt-4 text-xs text-[var(--color-graphite)]">La cuenta conserva su ficha e historial académico al retirar ALUMNO.</p></aside></section></AdminState></template>
    <template v-else><div class="mt-7 flex items-center justify-between"><div><h2 class="text-2xl font-semibold">{{ isCreate ? 'Nueva cuenta' : 'Editar cuenta' }}</h2><p class="text-[var(--color-graphite)]">La contraseña inicial se comunica manualmente y nunca se muestra en mensajes.</p></div><RouterLink v-if="isEdit" :to="{ name: 'admin-user-detail', params: { id: userId } }" class="text-[var(--color-brand)]">Cancelar</RouterLink></div><form class="mt-5 grid gap-4 rounded-xl border border-[var(--color-border)] bg-white p-6 sm:grid-cols-2" novalidate @submit.prevent="save"><div class="sm:col-span-2"><label class="font-semibold">Nombre y apellido<input v-model="form.apellidoNombre" class="admin-input" /></label><p v-if="fieldErrors.apellidoNombre" class="field-error">{{ fieldErrors.apellidoNombre }}</p></div><div><label class="font-semibold">DNI<input v-model="form.dni" inputmode="numeric" class="admin-input" /></label><p v-if="fieldErrors.dni" class="field-error">{{ fieldErrors.dni }}</p></div><div><label class="font-semibold">CUIL<input v-model="form.cuil" inputmode="numeric" class="admin-input" /></label><p v-if="fieldErrors.cuil" class="field-error">{{ fieldErrors.cuil }}</p></div><div><label class="font-semibold">Email<input v-model="form.email" type="email" class="admin-input" /></label><p v-if="fieldErrors.email" class="field-error">{{ fieldErrors.email }}</p></div><div><label class="font-semibold">Teléfono<input v-model="form.telefono" inputmode="tel" class="admin-input" /></label><p v-if="fieldErrors.telefono" class="field-error">{{ fieldErrors.telefono }}</p></div><div><label class="font-semibold">Nacimiento<input v-model="form.fechaNacimiento" type="date" class="admin-input" /></label><p v-if="fieldErrors.fechaNacimiento" class="field-error">{{ fieldErrors.fechaNacimiento }}</p></div><div v-if="isCreate"><label class="font-semibold">Rol inicial<select v-model="form.role" class="admin-input"><option>ALUMNO</option><option>PROFESOR</option><option>ADMINISTRATIVO</option></select></label></div><div v-if="isCreate"><label class="font-semibold">Contraseña inicial<input v-model="form.password" type="password" autocomplete="new-password" class="admin-input" /></label><p v-if="fieldErrors.password" class="field-error">{{ fieldErrors.password }}</p></div><div v-if="isCreate"><label class="font-semibold">Confirmar contraseña<input v-model="form.passwordConfirm" type="password" autocomplete="new-password" class="admin-input" /></label><p v-if="fieldErrors.passwordConfirm" class="field-error">{{ fieldErrors.passwordConfirm }}</p></div><template v-if="form.role === 'ALUMNO' || selected?.roles.includes('ALUMNO')"><div class="sm:col-span-2 border-t border-[var(--color-border)] pt-4"><h3 class="font-semibold">Ficha de alumno</h3></div><div class="sm:col-span-2"><label class="font-semibold">Domicilio<input v-model="form.domicilio" class="admin-input" /></label></div><div><label class="font-semibold">Año de egreso<input v-model="form.anioEgreso" type="number" class="admin-input" /></label></div><div><label class="font-semibold">Institución de procedencia<input v-model="form.institucionProcedencia" class="admin-input" /></label></div></template><div class="sm:col-span-2"><button type="submit" class="min-h-11 rounded-lg bg-[var(--color-brand)] px-5 font-semibold text-white disabled:opacity-50" :disabled="saving">{{ saving ? 'Guardando…' : 'Guardar cuenta' }}</button></div></form></template>
  </main>
</template>

<style scoped>
.admin-input { margin-top: .25rem; min-height: 2.75rem; width: 100%; border: 1px solid var(--color-border); border-radius: .5rem; padding: 0 .75rem; font-weight: 400; }
.field-error { margin-top: .25rem; font-size: .875rem; color: #a31118; }
</style>
